    // позиции только активных кораблей на текущем шаге
    const currentPositions: Record<string, Vector> = {};

    paths.forEach((path) => {
      if (path.hasCollided) {
        return; // уже заморожен
      }
      const shipStepTime = 1 / path.path.length;
      const currentStep = Math.min(
        path.path.length - 1,
        Math.floor(elapsedTime / shipStepTime),
      );
      path.currentStep = currentStep;
      currentPositions[path.ship.ship._id] = path.path[currentStep];
    });

    // проверяем только текущие позиции
    const rawCollisions = findEqualVectors(currentPositions);

    for (const { shipIds, position } of Object.values(rawCollisions)) {
      const collidedShips = paths.filter((p) =>
        shipIds.includes(p.ship.ship._id),
      );

      collidedShips.forEach((p) => {
        if (!p.hasCollided) {
          p.hasCollided = true;
        }
      });

      collisions.push({
        ships: collidedShips.map((p) => p.ship),
        position,
      });
    }
  }

  return collisions;
}
```

---

🔑 Отличия от твоего варианта:
1. `findEqualVectors` теперь работает с `Record<string, Vector>` (только **одна позиция на корабль**, а не массив).
2. Вместо `modifiedPaths` я сделал `currentPositions` на каждом шаге. История пути больше не хранится.
3. Коллизии проверяются только в рамках одного момента времени.  

---

