Хочешь, я скину минимальный полный пример проекта NestJS (с `AppModule`, `main.ts` и твоим `SeaCombatGateway`), чтобы ты смог проверить без правок?

Окей 👍  
В Godot 4 у любого `Resource` (и не только) можно получить список экспортируемых свойств через `get_property_list()`.  
На основе этого можно сделать универсальный конвертер → `Dictionary` → `JSON`.  

Вот пример утилиты:

```gdscript
func resource_to_dict(res: Resource) -> Dictionary:
	var result: Dictionary = {}
	for prop in res.get_property_list():
		var name = prop.name
		# Пропускаем внутренние служебные свойства
		if name.begins_with("_"):
			continue

		var value = res.get(name)

		if value is Resource:
			# Рекурсивно для вложенных ресурсов
			result[name] = resource_to_dict(value)
		elif value is Array:
			# Обрабатываем массивы, в том числе с ресурсами
			var arr: Array = []
			for v in value:
				if v is Resource:
					arr.append(resource_to_dict(v))
				else:
					arr.append(v)
			result[name] = arr
		elif value is Vector2 or value is Vector3:
			# Для векторов делаем компактный формат (массив чисел)
			result[name] = [value.x, value.y] if value is Vector2 else [value.x, value.y, value.z]
		else:
			result[name] = value
	return result


func resource_to_json(res: Resource) -> String:
	return JSON.stringify(resource_to_dict(res))
```

---

### Пример использования

```gdscript
extends Node
class_name TestJson

@export var my_resource: Resource

func _ready():
	var dict_form = resource_to_dict(my_resource)
	print(dict_form)

	var json_str = resource_to_json(my_resource)
	print(json_str)
```

---

### Вывод
- Любой ресурс будет превращён в словарь.  
- Вложенные ресурсы и массивы обрабатываются рекурсивно.  
- Вектора сериализуются как массивы чисел (`[x, y]`).  

👉 Хочешь, я добавлю ещё автоматическую обработку `Color` и `Transform2D/Transform3D`, чтобы сразу можно было весь игровой state сливать на сервер в JSON?

Коротко — причина ошибки и два простых решения (одно «правильное» и универсальное, второе — быстрое).

**Причина:** `has_property` в Godot **не существует**. У `Object`/`RefCounted` есть методы `get_property_list()` и `get()`, но `get_property_list()` возвращает список *отражённых* (в основном экспортированных / объявленных) свойств; если класс — просто `RefCounted` с обычными `var` без `@export`, то этот список может быть пустым — поэтому твоё обращение к несуществующему `has_property` привело к ошибке.

### Вариант A. Самый простой и надёжный — сделать класс сериализуемым напрямую
Если ты можешь править класс сообщения — просто реализуй `to_dict()` или унаследуй от `Resource` и используй `get_property_list()`.

**Пример (реальный и надёжный):**
```gdscript
# UserConnectedMessage.gd
extends RefCounted
class_name UserConnectedMessage

var userId: String

func _init(player):
    userId = player._id

func to_dict() -> Dictionary:
    return {"userId": userId}
```

Отправка:
```gdscript
var msg = UserConnectedMessage.new(player)
var json = JSON.stringify(msg.to_dict())
socket.get_peer(1).put_packet(json.to_utf8_buffer())  # или socket.send_text(json)
```

> Плюсы: просто, прозрачно, контроль над тем, что попадёт в JSON. Рекомендую этот вариант для сетевых сообщений.

---

### Вариант B. Универсальный сериализатор (для Resource / Object / вложенных структур)
Если нужно сериализовать разные ресурсы/объекты рекурсивно, используй универсальную функцию, которая:
- обрабатывает `Resource` (через `get_property_list()`),
- обрабатывает `Array`/`Dictionary`,
- сворачивает `Vector2/Vector3/Color` в массивы,
- если объект имеет `to_dict()` — вызывает его,
- иначе — делает `str(value)` как запасной вариант.

Вот готовая реализация (скопируй в utils.gd и подключай):

```gdscript
# utils.gd
func _value_to_primitive(value):
    # Resource -> рекурсивно
    if value is Resource:
        return resource_to_dict(value)

    # Array -> рекурсивно
    if value is Array:
        var out_arr := []
        for v in value:
            out_arr.append(_value_to_primitive(v))
        return out_arr

    # Dictionary -> рекурсивно
    if value is Dictionary:
        var out_dict := {}
        for k in value.keys():
            out_dict[k] = _value_to_primitive(value[k])
        return out_dict

