func resource_to_dict(res: Resource) -> Dictionary:
    var out := {}
    for prop in res.get_property_list():
        var name = prop["name"]
        if name.begins_with("_"):
            continue
        var v = res.get(name)
        out[name] = _value_to_primitive(v)
    return out


func object_to_dict(obj: Object) -> Dictionary:
    # Если это Resource — делегируем
    if obj is Resource:
        return resource_to_dict(obj)

    # Если есть to_dict — используем
    if obj.has_method("to_dict"):
        return _value_to_primitive(obj.to_dict())

    # Если есть отражаемые свойства — соберём их
    var props = obj.get_property_list()
    if props.size() > 0:
        var o := {}
        for prop in props:
            var name = prop["name"]
            if name.begins_with("_"):
                continue
            o[name] = _value_to_primitive(obj.get(name))
        return o

    # Ничего не нашли — вернём строковое представление
    return {"value": str(obj)}


